/*
 * =========================================================
 * BIG BROTHER SIMULATOR — PRE-JURY CENTERING FIX
 * =========================================================
 *
 * Centers the pre-jury placement cards and portraits.
 *
 * This version targets the actual .single-finale-grid
 * generated by finale-controller.js.
 */

(function () {
    "use strict";

    function centerPreJury() {

        const headings = Array.from(
            document.querySelectorAll("h3")
        );

        const heading = headings.find(h =>
            h.textContent
                .trim()
                .toLowerCase() === "pre-jury houseguests"
        );

        if (!heading) {
            return;
        }

        const section =
            heading.closest("section") ||
            heading.parentElement;

        if (!section) {
            return;
        }

        /*
         * The current finale controller creates:
         *
         * <div class="single-finale-grid">
         *
         * It does NOT use an inline grid-template-columns
         * style attribute.
         */
        const grid =
            section.querySelector(
                ".single-finale-grid"
            );

        if (!grid) {
            return;
        }

        /* Center the entire grid. */
        grid.style.width = "100%";
        grid.style.maxWidth = "1000px";
        grid.style.marginLeft = "auto";
        grid.style.marginRight = "auto";

        grid.style.display = "grid";

        grid.style.justifyContent = "center";
        grid.style.justifyItems = "center";
        grid.style.alignItems = "start";

        /*
         * Center every Houseguest card.
         */
        Array.from(grid.children).forEach(card => {

            card.style.width = "140px";
            card.style.minWidth = "140px";
            card.style.maxWidth = "140px";

            card.style.marginLeft = "auto";
            card.style.marginRight = "auto";

            card.style.display = "flex";
            card.style.flexDirection = "column";

            card.style.alignItems = "center";
            card.style.justifyContent = "flex-start";

            card.style.textAlign = "center";

            /*
             * Center the portrait wrapper.
             */
            const portrait =
                card.querySelector(".sim-portrait");

            if (portrait) {

                portrait.style.width = "120px";
                portrait.style.minWidth = "120px";
                portrait.style.maxWidth = "120px";

                portrait.style.marginLeft = "auto";
                portrait.style.marginRight = "auto";

                portrait.style.alignSelf = "center";

                portrait.style.textAlign = "center";

                /*
                 * Center the actual image.
                 */
                const image =
                    portrait.querySelector("img");

                if (image) {

                    image.style.width = "120px";
                    image.style.height = "145px";

                    image.style.display = "block";

                    image.style.marginLeft = "auto";
                    image.style.marginRight = "auto";
                }
            }

        });
    }

    function apply() {

        centerPreJury();

        setTimeout(
            centerPreJury,
            100
        );

        setTimeout(
            centerPreJury,
            500
        );

        setTimeout(
            centerPreJury,
            1000
        );
    }

    /*
     * Initial page load.
     */
    if (
        document.readyState === "loading"
    ) {

        document.addEventListener(
            "DOMContentLoaded",
            apply
        );

    } else {

        apply();

    }

    /*
     * Finale results are generated dynamically,
     * so watch for new elements being inserted.
     */
    const observer =
        new MutationObserver(() => {

            centerPreJury();

        });

    observer.observe(
        document.body,
        {
            childList: true,
            subtree: true
        }
    );

    console.log(
        "PRE-JURY CENTERING FIX loaded."
    );

})();
